package com.example.hopes.data.remote

import com.example.hopes.core.network.ApiExecutor
import com.example.hopes.core.network.NetworkResult
import com.example.hopes.data.api.*
import javax.inject.Inject

interface AuthRemoteDataSource { suspend fun login(body: LoginRequestDto): NetworkResult<TokenResponseDto>; suspend fun signUp(body: SignupRequestDto): NetworkResult<TokenResponseDto>; suspend fun sendSignupCode(body: EmailRequestDto): NetworkResult<MessageEnvelopeDto>; suspend fun confirmSignupCode(body: EmailCodeRequestDto): NetworkResult<MessageEnvelopeDto>; suspend fun requestPasswordReset(body: EmailRequestDto): NetworkResult<MessageEnvelopeDto>; suspend fun resetPassword(body: PasswordResetRequestDto): NetworkResult<MessageEnvelopeDto> }
class AuthRemoteDataSourceImpl @Inject constructor(private val apiExecutor: ApiExecutor, private val authApiService: AuthApiService) : AuthRemoteDataSource {
    override suspend fun login(body: LoginRequestDto) = apiExecutor.execute { authApiService.login(body) }; override suspend fun signUp(body: SignupRequestDto) = apiExecutor.execute { authApiService.signUp(body) }; override suspend fun sendSignupCode(body: EmailRequestDto) = apiExecutor.execute { authApiService.sendSignupVerification(body) }; override suspend fun confirmSignupCode(body: EmailCodeRequestDto) = apiExecutor.execute { authApiService.confirmSignupVerification(body) }; override suspend fun requestPasswordReset(body: EmailRequestDto) = apiExecutor.execute { authApiService.requestPasswordReset(body) }; override suspend fun resetPassword(body: PasswordResetRequestDto) = apiExecutor.execute { authApiService.resetPassword(body) }
}
interface ChatRemoteDataSource { suspend fun main(keyword: String?, page: Int, size: Int): NetworkResult<MainResponseDto>; suspend fun chat(id: Long, page: Int, size: Int): NetworkResult<ChatResponseDto>; suspend fun create(body: CreateChatRequestDto): NetworkResult<ChatResponseDto>; suspend fun send(id: Long, body: SendMessageRequestDto): NetworkResult<ChatResponseDto> }
class ChatRemoteDataSourceImpl @Inject constructor(private val apiExecutor: ApiExecutor, private val chatApiService: ChatApiService) : ChatRemoteDataSource { override suspend fun main(keyword: String?, page: Int, size: Int) = apiExecutor.execute { chatApiService.getMain(keyword, page, size) }; override suspend fun chat(id: Long, page: Int, size: Int) = apiExecutor.execute { chatApiService.getChat(id, page, size) }; override suspend fun create(body: CreateChatRequestDto) = apiExecutor.execute { chatApiService.createChat(body) }; override suspend fun send(id: Long, body: SendMessageRequestDto) = apiExecutor.execute { chatApiService.sendMessage(id, body) } }
interface SettingsRemoteDataSource { suspend fun logout(): NetworkResult<MessageEnvelopeDto>; suspend fun theme(body: ThemeRequestDto): NetworkResult<ThemeResponseDto>; suspend fun profile(): NetworkResult<UserResponseDto>; suspend fun updateProfile(body: MyPageUpdateRequestDto): NetworkResult<UserResponseDto>; suspend fun settings(): NetworkResult<SettingMainResponseDto>; suspend fun updateSettings(body: SettingUpdateRequestDto): NetworkResult<SettingMainResponseDto>; suspend fun inquiry(body: ContentRequestDto): NetworkResult<MessageEnvelopeDto> }
class SettingsRemoteDataSourceImpl @Inject constructor(private val apiExecutor: ApiExecutor, private val settingsApiService: SettingsApiService) : SettingsRemoteDataSource { override suspend fun logout() = apiExecutor.execute { settingsApiService.logout() }; override suspend fun theme(body: ThemeRequestDto) = apiExecutor.execute { settingsApiService.updateTheme(body) }; override suspend fun profile() = apiExecutor.execute { settingsApiService.getMyPage() }; override suspend fun updateProfile(body: MyPageUpdateRequestDto) = apiExecutor.execute { settingsApiService.updateMyPage(body) }; override suspend fun settings() = apiExecutor.execute { settingsApiService.getSettings() }; override suspend fun updateSettings(body: SettingUpdateRequestDto) = apiExecutor.execute { settingsApiService.updateSettings(body) }; override suspend fun inquiry(body: ContentRequestDto) = apiExecutor.execute { settingsApiService.submitInquiry(body) } }
